new='''def check(req, extra_validate=True, verbose=False):
    """Run a request; verify answers against the reference, images against the spec."""
    req_v = json.loads(req)
    resp = run(req)
    if 'error' in resp:
        raise SystemExit('unexpected error: %s' % resp)
    results = resp['results']
    if len(results) != len(req_v['cases']):
        raise SystemExit('case count')
    for ci, (case, res) in enumerate(zip(req_v['cases'], results)):
        if set(res) != {'answers', 'snapshots', 'loads'}:
            raise SystemExit('result keys')
        fib = Fib()
        exp = []
        si = 0
        li = 0
        loaded = None
        for op in case['ops']:
            if op[0] == 'put':
                fib.put(op[1], op[2], op[3])
            elif op[0] == 'query':
                for a in op[1]:
                    exp.append(fib.lpm(a))
            elif op[0] == 'image_query':
                for a in op[1]:
                    exp.append(loaded.lookup(a) if loaded is not None else None)
            elif op[0] == 'save':
                si += 1
            elif op[0] == 'load_saved':
                loaded = Image(res['snapshots'][op[1]])
                li += 1
            elif op[0] == 'load':
                try:
                    pyok = Image(op[1]) is not None
                except Bad:
                    pyok = False
                loaded = Image(op[1]) if res['loads'][li] else loaded
                if pyok != res['loads'][li]:
                    raise SystemExit('case %d load op %d: cpp=%s python=%s' % (ci, li, res['loads'][li], pyok))
                li += 1
            else:
                raise SystemExit('unknown op')
        if res['answers'] != exp:
            for _i, (_a, _b) in enumerate(zip(res['answers'], exp)):
                if _a != _b:
                    raise SystemExit('case %d answers mismatch at %d: got %r exp %r' % (ci, _i, _a, _b))
            raise SystemExit('case %d answers mismatch (lengths %d vs %d)' % (ci, len(res['answers']), len(exp)))
        if len(res['snapshots']) != si:
            raise SystemExit('snapshot count')
        if len(res['loads']) != li:
            raise SystemExit('load count')
        for img in res['snapshots']:
            Image(img)   # raises Bad on any violation
        for b in res['loads']:
            if type(b) is not bool:
                raise SystemExit('load type')
        if verbose:
            print('case %d ok: %d answers, %d snapshots, %d loads' %
                  (ci, len(res['answers']), len(res['snapshots']), len(res['loads'])))
    return resp
'''
s=s[:old_start]+new+s[old_end:]
open(p,'w').write(s)
